-- public.bauble_text(p_kind text, p_key text, p_amount double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.bauble_text(p_kind text, p_key text, p_amount double precision)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case when p_kind = 'plus'
    then rtrim(p_key || ': +' || round(p_amount)::int || ' '
               || coalesce((select a.said from bauble_ancient a where a.id = p_key), ''))
    else (select replace(p_key, '_', ' ') || ': ' || k.lead || to_char(p_amount, 'FM990.0') || k.tail
            from bauble_kind k where k.id = p_kind)
  end
$function$
